"""Build BBLO's public membership overview from approved fees and real activity media."""
from pathlib import Path
from html import escape
from urllib.parse import quote
import hashlib
import json
import re
from bblo_advertising_rates import cards as advertising_cards, note as advertising_note, assets as advertising_assets

ROOT=Path(__file__).resolve().parents[1]
ROUTE='/bblo/benefits/'
ORIGIN='https://doitwithtlc.com'

def esc(value):return escape(str(value),quote=True)
def section(body,cls='',id=''):
    return '<section'+(' id="'+id+'"' if id else '')+' class="'+cls+'"><div class="wrap">'+body+'</div></section>'
def button(url,label,secondary=False):
    return '<a class="button'+(' secondary' if secondary else '')+'" href="'+esc(url)+'">'+label+'</a>'
def membership_url(plan):
    return 'mailto:carmen@doitwithtlc.com?subject='+quote('BBLO membership: '+plan)+'&body='+quote('I would like information about '+plan+'.\n\nMy name:\nBusiness:\nWhat we do:\nPhone:\n\nPlease send the current application and next steps.\n')
def photo(src,alt,caption,route,hero=False):
    return '<figure class="membership-photo"><a href="'+route+'" aria-label="'+esc('View album: '+caption)+'"><img src="'+src+'" alt="'+esc(alt)+'"'+(' fetchpriority="high"' if hero else ' loading="lazy"')+' decoding="async" width="1400" height="1050"></a><figcaption>'+esc(caption)+'</figcaption></figure>'

def build():
    page=ROOT/'bblo/benefits/index.html';template=page.read_text()
    hero=section('<div class="membership-hero-layout"><div><p class="eyebrow">Bilingual Business Leaders of Ocala · A TLC program</p><h1>We build businesses.<br><em>Not just connections.</em></h1><p class="lead">A business community that puts relationships, practical learning and local visibility into action.</p><p>BBLO brings business owners and professionals together in Ocala and Marion County through regular meetings, member presentations, referrals, Field Trip Fridays and community involvement.</p><p class="membership-bilingual"><strong>You don’t have to speak Spanish to join.</strong></p><div class="actions">'+button('#membership-price','See membership options')+button('/bblo/visit/','Plan your first visit',True)+'</div></div>'+photo('/assets/curated-bblo/20260828/20260828_103010.webp','BBLO participants together at Media Minds','BBLO meeting at Media Minds · August 28, 2026','/bblo/gallery/2026-08-28/',True)+'</div>','hero membership-hero')
    jump='<nav class="membership-jump" aria-label="Membership page sections"><div class="wrap">'+''.join('<a href="#'+href+'">'+label+'</a>' for href,label in [('about-membership','What is BBLO?'),('membership-benefits','Benefits'),('membership-in-action','Photos & activities'),('membership-price','Membership cost'),('annual-value','Annual savings'),('membership-addons','Optional add-ons')])+'</div></nav>'
    body=hero+jump
    body+=section('<div class="membership-intro"><div><p class="eyebrow">What is BBLO?</p><h2>A place to know the people<br>behind the businesses.</h2><p>Bilingual Business Leaders of Ocala is a community and visibility program under The Liaison Companies LLC, founded by Carmen Garcia Tirado. Members get to know one another’s services, share knowledge, make relevant connections and participate in the local business community.</p><p>English and Spanish are both welcome. You can participate without being bilingual.</p></div><aside class="membership-meeting"><p class="eyebrow">Your Friday connection</p><h3>Fridays · 8–10 AM</h3><p>Regular meetings are at Media Minds in north Ocala.</p><p>Field Trip Fridays may have a different location or start time. Check the published calendar before traveling.</p>'+button('/bblo/events/','See upcoming meetings & visits',True)+'</aside></div>','', 'about-membership')
    benefits=[
        ('01','Relationships & referrals','Learn what other members do, build one-to-one relationships and make introductions that fit the business and the need.'),
        ('02','Business learning','Participate in scheduled presentations, business conversations, workshops and training. Bring questions you can put to work in your business.'),
        ('03','Your public business profile','A dedicated business page and standard directory listing are included with paid membership, with your services, approved links and available photos or logo.'),
        ('04','Member visibility','Introduce your business, get to know the people in the room and participate in member spotlight opportunities as they are scheduled.'),
        ('05','Field Trip Friday','Visit businesses and community organizations, learn firsthand about their work and discover where useful connections can happen.'),
        ('06','Community involvement','Meet local nonprofit leaders, learn about community needs and participate in scheduled group activities.'),
        ('07','Private member hub','Access BBLO member updates, resources, shared photos, videos and event information after approval and sign-in.'),
        ('08','Member partner offers','Explore current BBLO offers from C-Suiteware and Media Minds. Partner services have their own pricing and eligibility requirements.')]
    body+=section('<p class="eyebrow">Included with paid membership</p><h2>More ways for your business<br>to participate and be seen.</h2><div class="membership-benefit-grid">'+''.join('<article class="card"><span class="membership-number">'+num+'</span><h3>'+title+'</h3><p>'+copy+'</p></article>' for num,title,copy in benefits)+'</div><p class="membership-note">Activities follow the published schedule. Check individual listings for any separate registration, travel or activity costs. Referrals, sales and presentation slots are not guaranteed.</p>','', 'membership-benefits')
    body+='<!-- included-member-profile:start -->'+section('<div class="membership-profile-feature"><div><p class="eyebrow">Your membership already includes this</p><h2>Your business gets<br>its own public page.</h2><p>Give someone a link that explains who you are, what you offer and how to connect. Your profile appears in the BBLO directory and is made eligible for Google indexing.</p><ul><li>Business description, services and specialties</li><li>Verified service areas and approved business contact links</li><li>Your approved photo or unchanged logo when supplied</li><li>A shareable profile URL and reviewed profile updates</li></ul><p class="membership-note">Search engines determine indexing and rankings. Optional advertising gives you an additional on-site placement.</p></div><div class="membership-profile-links">'+button('/bblo/members/','Explore member profiles')+button('/bblo/profile-update/','Send your profile information',True)+button('/bblo/member-center/','Member Login',True)+'</div></div>','membership-profile-section')+'<!-- included-member-profile:end -->'
    galleries=[
        ('/assets/curated-bblo/20261009/fb_img_1791564240253.webp','BBLO participants around a table at Media Minds','Business conversations at Media Minds · October 9, 2026','/bblo/gallery/2026-10-09/'),
        ('/assets/curated-bblo/20260814/img-20260814-wa0011.webp','BBLO visitors at Marion County Emergency Operations Center','Field Trip Friday · Emergency Management · August 14, 2026','/bblo/community-impact/emergency-management-tour/'),
        ('/assets/curated-bblo/20260515/img_20260515_170917.webp','BBLO group together during the Rancho Reposo visit','Community visit · Rancho Reposo · May 15, 2026','/bblo/community-impact/rancho-reposo/'),
        ('/assets/bblo/community/habitat-group.webp','Participants together at the Habitat Vet Build site','Community involvement · Habitat Vet Build · July 10, 2026','/bblo/community-impact/habitat-vet-build/')]
    body+=section('<p class="eyebrow">BBLO in action</p><h2>Meetings are only<br>part of the picture.</h2><p>See the conversations, visits and community activities behind the membership. Open a photo to explore its album.</p><div class="membership-gallery">'+''.join(photo(*g) for g in galleries)+'</div><div class="actions">'+button('/bblo/gallery/','Explore BBLO in Action')+button('/bblo/field-trip-friday/','Field Trip Friday',True)+'</div>','', 'membership-in-action')
    plans=[
        ('Monthly membership','$40','per month','Recurring on the 1st.','A monthly payment option for ongoing participation.','New application + first month: <strong>$105</strong>.','Monthly membership',False),
        ('Annual single membership','$450','per year','Save $30 on annual dues.','Equivalent to $37.50 per month, paid as one annual membership payment.','New application + annual single dues: <strong>$515</strong>.','Annual single membership',True),
        ('Annual dual membership','$600','per year','Ask about dual membership.','Confirm who qualifies for the dual arrangement and the application requirements before applying.','Application fees are additional; confirm the total for your arrangement.','Annual dual membership',False)]
    body+=section('<p class="eyebrow">Membership cost</p><h2>Choose how you<br>pay for participation.</h2><p>Core membership benefits are included with each approved membership. Optional advertising and separately priced partner services are additional.</p><div class="membership-price-grid">'+''.join('<article class="membership-plan'+(' annual-plan' if annual else '')+'">'+('<span class="membership-save">Annual savings</span>' if annual else '')+'<h3>'+name+'</h3><p class="membership-price">'+price+'<span>'+period+'</span></p><p><strong>'+line+'</strong></p><p>'+copy+'</p><p class="membership-total">'+total+'</p>'+button(membership_url(plan),'Ask about '+('annual single' if annual else 'dual membership' if 'dual' in plan else 'monthly'),True)+'</article>' for name,price,period,line,copy,total,plan,annual in plans)+'</div><div class="membership-fee-strip"><div><strong>$65 application fee</strong><p>Non-refundable and separate from membership dues.</p></div><div><strong>Your first two visits are free</strong><p>Come meet the community before applying.</p></div><div><strong>$20 drop-in</strong><p>Per visit after your two free visits.</p></div></div><p class="membership-note">Membership is subject to committee review and final approval. Inquiry buttons open your email app so you can request the current application and next steps; they do not collect payment.</p>','', 'membership-price')
    body+=section('<div class="membership-annual-layout"><div><p class="eyebrow">Why pay the full year?</p><h2>One year.<br>One membership payment.<br><em>$30 less in dues.</em></h2><p>The annual single plan costs $450, compared with $480 for twelve $40 monthly payments.</p><ul><li><strong>Save $30:</strong> 6.25% less than paying single membership dues monthly for twelve months.</li><li><strong>Simplify payments:</strong> one annual dues payment instead of twelve monthly dues payments.</li><li><strong>Plan your year:</strong> pay your annual membership dues upfront and focus on participating.</li></ul></div><div class="membership-annual-math"><p>Twelve monthly dues payments</p><p class="membership-math-number">$480</p><p>Annual single dues payment</p><p class="membership-math-number membership-gold">$450</p><hr><p><strong>You save $30 per year</strong><br>$37.50 per month equivalent</p></div></div><p class="membership-note">The $65 application fee is additional in both comparisons. New-applicant first-year totals are $545 with twelve monthly payments or $515 with annual single membership. Optional advertising is priced separately for all membership plans.</p>','membership-annual', 'annual-value')
    body+=section('<p class="eyebrow">Optional add-ons</p><h2>Your profile is included.<br>Extra placement is your choice.</h2><p>Choose optional Sponsored placement or a separately produced business story for additional visibility.</p>'+advertising_cards()+advertising_note()+button('/bblo/advertise/','See advertising details &amp; booking terms',True)+'<div class="membership-partner-callout"><h3>Business tools &amp; partner services</h3><p>Current BBLO member offers include C-Suiteware and Media Minds services. These are separately purchased services; confirm the current member offer and scope before booking.</p>'+button('/bblo/partners/','Explore member partner offers',True)+'</div>','', 'membership-addons')
    faqs=[
        ('Do I need to speak Spanish?','No. BBLO welcomes English- and Spanish-speaking business owners and professionals. You do not have to be bilingual to participate.'),
        ('Can I visit before applying?','Yes. Your first two visits are free. Drop-ins after those visits are $20 per visit. Check the calendar and visitor information before attending.'),
        ('Is my public business profile an extra charge?','Your standard public business profile and directory listing are included with paid BBLO membership. Optional advertising placements are purchased separately.'),
        ('What do I save by paying annually?','Annual single membership is $450, compared with $480 for twelve $40 monthly dues payments. That saves $30 per year. The $65 application fee is separate in either case.'),
        ('What does annual dual membership cover?','Annual dual membership is $600. Contact BBLO to confirm the qualifying arrangement and application requirements for the people or businesses involved.'),
        ('Are Field Trip Fridays always at the regular meeting location?','No. Field trips may meet at another location or start at a different time. Check the individual event listing before traveling.'),
        ('How do I join?','Start with a visit, then request the current application and payment instructions. Membership is subject to committee review and final approval.')]
    body+=section('<p class="eyebrow">Before you join</p><h2>A few helpful answers.</h2><div class="membership-faq">'+''.join('<details><summary>'+esc(q)+'</summary><p>'+esc(a)+'</p></details>' for q,a in faqs)+'</div>','', 'membership-questions')
    body+=section('<p class="eyebrow">Your next Friday connection</p><h2>Come meet the people<br>behind the businesses.</h2><p>Bring your business, your questions and a clear introduction. Your first two visits are free.</p><div class="actions">'+button('/bblo/visit/','Plan my first visit')+button('/bblo/join/','How to join',True)+button(membership_url('BBLO membership'),'Ask Carmen about membership',True)+'</div>','membership-final')
    title='BBLO Membership, Benefits & Pricing in Ocala | TLC'
    description='Explore BBLO membership in Ocala: business connections, learning, field trips and a public business profile. $40 monthly, $450 annual single or $600 annual dual.'
    text=re.sub(r'<main\b[^>]*>.*?</main>',lambda _:'<main id="main" class="membership-overview" data-membership-overview="complete">'+body+'</main>',template,flags=re.S)
    text=re.sub(r'<title>.*?</title>',lambda _:'<title>'+title+'</title>',text)
    for key,value in [('description',description),('og:title',title),('og:description',description),('og:url',ORIGIN+ROUTE),('og:image',ORIGIN+'/assets/curated-bblo/20260828/20260828_103010.webp')]:
        text=re.sub(r'(<meta (?:name|property)="'+key+'" content=")[^"]*(">)',lambda m:m[1]+esc(value)+m[2],text)
    text=re.sub(r'<script type="application/ld\+json">.*?</script>','',text,flags=re.S)
    text=re.sub(r'<link[^>]+href="/assets/bblo/membership-overview.css[^>]*>','',text)
    version=hashlib.sha256((ROOT/'assets/bblo/membership-overview.css').read_bytes()).hexdigest()[:12]
    schema=[{'@context':'https://schema.org','@type':'WebPage','url':ORIGIN+ROUTE,'name':title,'description':description,'about':{'@type':'Organization','name':'Bilingual Business Leaders of Ocala','alternateName':'BBLO','url':ORIGIN+'/bblo/','parentOrganization':{'@type':'Organization','name':'The Liaison Companies LLC','url':ORIGIN+'/'}}},{'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in faqs]}]
    head='<link rel="stylesheet" href="/assets/bblo/membership-overview.css?v='+version+'">'+''.join('<script type="application/ld+json">'+json.dumps(s,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')+'</script>' for s in schema)
    text=re.sub(r'<(?:link|script)[^>]+(?:href|src)="/assets/bblo/advertising-rates\.(?:css|js)[^>]*>(?:</script>)?', '', text)
    text=text.replace('</head>',head+advertising_assets()+'</head>');page.write_text(text)
    about=ROOT/'bblo/index.html';s=about.read_text()
    if 'data-membership-overview-link' not in s:
        s=re.sub(r'(<main\b[^>]*>.*?<div class="actions">)',lambda m:m[1]+'<a class="button secondary" data-membership-overview-link href="/bblo/benefits/">Membership benefits &amp; pricing</a>',s,count=1,flags=re.S)
        about.write_text(s)

if __name__=='__main__':
    build()
    print('BBLO membership overview refreshed with approved fees, annual savings and real activity photos.')
